import pytest
import click


def test_func_param_type_value_error_message():
    class MyClass:
        def __init__(self, value):
            self.value = value

        @staticmethod
        def from_str(input_value):
            if input_value != "works":
                raise ValueError(f"input was {input_value!r}, should be 'works'")
            return MyClass(input_value)

    my_class_type = click.FuncParamType(MyClass.from_str)

    with pytest.raises(click.BadParameter) as exc_info:
        my_class_type.convert("fails", None, None)

    assert "input was 'fails', should be 'works'" in str(exc_info.value)
